/****** Object:  StoredProcedure [dbo].[sp_BigQuery_SaveDataset]    Script Date: 7/11/2026 3:25:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE PROCEDURE [dbo].[sp_BigQuery_SaveDataset]
    @DatasetId        NVARCHAR(200),
    @ProjectId        NVARCHAR(200),
    @FriendlyName     NVARCHAR(500),
    @Description      NVARCHAR(MAX),
    @Location         NVARCHAR(100),
    @CreatedAt        BIGINT,
    @LastModifiedTime BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM BigQueryDataset WHERE DatasetId = @DatasetId AND ProjectId = @ProjectId)
    BEGIN
        UPDATE BigQueryDataset
        SET FriendlyName = @FriendlyName, Description = @Description,
            LastModifiedTime = @LastModifiedTime
        WHERE DatasetId = @DatasetId AND ProjectId = @ProjectId;
    END
    ELSE
    BEGIN
        INSERT INTO BigQueryDataset (DatasetId, ProjectId, FriendlyName, Description, Location, CreatedAt, LastModifiedTime, LocalCreatedAt)
        VALUES (@DatasetId, @ProjectId, @FriendlyName, @Description, @Location, @CreatedAt, @LastModifiedTime, GETUTCDATE());
    END
END

GO
