CREATE PROCEDURE [dbo].[sp_BigQuery_SaveJob]
    @JobId               NVARCHAR(500),
    @ProjectId           NVARCHAR(200),
    @JobType             NVARCHAR(100),
    @Status              NVARCHAR(100),
    @CreationTime        BIGINT,
    @StartTime           BIGINT,
    @EndTime             BIGINT,
    @TotalRows           BIGINT,
    @TotalBytesProcessed BIGINT,
    @Query               NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO BigQueryJob (JobId, ProjectId, JobType, Status, CreationTime, StartTime, EndTime, TotalRows, TotalBytesProcessed, Query, LocalCreatedAt)
    VALUES (@JobId, @ProjectId, @JobType, @Status, @CreationTime, @StartTime, @EndTime, @TotalRows, @TotalBytesProcessed, @Query, GETUTCDATE());
END

