GO
CREATE PROCEDURE [dbo].[sp_BigQuery_SaveTable]
    @TableId          NVARCHAR(200),
    @DatasetId        NVARCHAR(200),
    @ProjectId        NVARCHAR(200),
    @Type             NVARCHAR(100),
    @FriendlyName     NVARCHAR(500),
    @Description      NVARCHAR(MAX),
    @NumRows          BIGINT,
    @NumBytes         BIGINT,
    @CreatedTime      BIGINT,
    @LastModifiedTime BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM BigQueryTableInfo WHERE TableId = @TableId AND DatasetId = @DatasetId AND ProjectId = @ProjectId)
    BEGIN
        UPDATE BigQueryTableInfo
        SET Type = @Type, FriendlyName = @FriendlyName, Description = @Description,
            NumRows = @NumRows, NumBytes = @NumBytes, LastModifiedTime = @LastModifiedTime
        WHERE TableId = @TableId AND DatasetId = @DatasetId AND ProjectId = @ProjectId;
    END
    ELSE
    BEGIN
        INSERT INTO BigQueryTableInfo (TableId, DatasetId, ProjectId, Type, FriendlyName, Description, NumRows, NumBytes, CreatedTime, LastModifiedTime, LocalCreatedAt)
        VALUES (@TableId, @DatasetId, @ProjectId, @Type, @FriendlyName, @Description, @NumRows, @NumBytes, @CreatedTime, @LastModifiedTime, GETUTCDATE());
    END
END

GO
