CREATE PROCEDURE [dbo].[sp_Cloud_UpdateToken]
    @Id           INT,
    @ProjectId    NVARCHAR(256),
    @AccessToken  NVARCHAR(2048),
    @RefreshToken NVARCHAR(2048),
    @ExpiresAt    DATETIME2,
    @Scope        NVARCHAR(1024),
    @UpdatedAt    DATETIME2
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE Cloud_Tokens
    SET
        AccessToken  = @AccessToken,
        RefreshToken = ISNULL(@RefreshToken, RefreshToken),
        ExpiresAt    = @ExpiresAt,
        Scope        = @Scope,
        UpdatedAt    = @UpdatedAt
    WHERE Id = @Id AND ProjectId = @ProjectId;
END

