CREATE PROCEDURE [dbo].[sp_Facebook_Ad_Save]
    @AdId       NVARCHAR(50),
    @AdSetId    NVARCHAR(50),
    @CampaignId NVARCHAR(50),
    @AccountId  NVARCHAR(50),
    @AdName     NVARCHAR(500),
    @AdStatus   NVARCHAR(50)  = NULL,
    @CreativeId NVARCHAR(50)  = NULL,
    @BidAmount  DECIMAL(18,2) = NULL,
    @BidType    NVARCHAR(50)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    MERGE Facebook_Ads AS target
    USING (SELECT @AdId AS AdId) AS source
    ON target.AdId = source.AdId
    WHEN MATCHED THEN
        UPDATE SET AdName = @AdName, AdStatus = @AdStatus, CreativeId = @CreativeId,
                   BidAmount = @BidAmount, BidType = @BidType, UpdatedAt = GETDATE()
    WHEN NOT MATCHED THEN
        INSERT (AdId, AdSetId, CampaignId, AccountId, AdName, AdStatus, CreativeId, BidAmount, BidType, CreatedAt, UpdatedAt)
        VALUES (@AdId, @AdSetId, @CampaignId, @AccountId, @AdName, @AdStatus, @CreativeId, @BidAmount, @BidType, GETDATE(), GETDATE());
END

