CREATE PROCEDURE [dbo].[sp_Facebook_Auth_SaveToken]
    @UserId         NVARCHAR(50),
    @PageId         NVARCHAR(50)  = NULL,
    @AccessToken    NVARCHAR(MAX),
    @TokenType      NVARCHAR(50)  = 'user',
    @ExpiresAt      DATETIME      = NULL,
    @LongLivedToken NVARCHAR(MAX) = NULL,
    @Scope          NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    MERGE Facebook_Tokens AS target
    USING (SELECT @UserId AS UserId, @PageId AS PageId) AS source
    ON target.UserId = source.UserId AND (target.PageId = source.PageId OR (target.PageId IS NULL AND source.PageId IS NULL))
    WHEN MATCHED THEN
        UPDATE SET
            AccessToken    = @AccessToken,
            TokenType      = @TokenType,
            ExpiresAt      = @ExpiresAt,
            LongLivedToken = @LongLivedToken,
            Scope          = @Scope,
            UpdatedAt      = GETDATE()
    WHEN NOT MATCHED THEN
        INSERT (UserId, PageId, AccessToken, TokenType, ExpiresAt, LongLivedToken, Scope, CreatedAt, UpdatedAt)
        VALUES (@UserId, @PageId, @AccessToken, @TokenType, @ExpiresAt, @LongLivedToken, @Scope, GETDATE(), GETDATE());
END

GO
