CREATE PROCEDURE [dbo].[sp_Facebook_Auth_UpdateToken]
    @UserId         NVARCHAR(50),
    @PageId         NVARCHAR(50)  = NULL,
    @AccessToken    NVARCHAR(MAX),
    @TokenType      NVARCHAR(50)  = 'user',
    @ExpiresAt      DATETIME      = NULL,
    @LongLivedToken NVARCHAR(MAX) = NULL,
    @Scope          NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE Facebook_Tokens
    SET AccessToken    = @AccessToken,
        TokenType      = @TokenType,
        ExpiresAt      = @ExpiresAt,
        LongLivedToken = @LongLivedToken,
        Scope          = @Scope,
        UpdatedAt      = GETDATE()
    WHERE UserId = @UserId
      AND (PageId = @PageId OR (PageId IS NULL AND @PageId IS NULL));
END

