CREATE PROCEDURE [dbo].[sp_Facebook_Insight_GetAd]
    @AccountId NVARCHAR(50),
    @Since     DATETIME = NULL,
    @Until     DATETIME = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT Id, AccountId, CampaignId, AdSetId, AdId, Impressions, Reach, Clicks, Spend, Cpc, Cpm, Ctr, DateStart, DateStop, CreatedAt
    FROM Facebook_AdInsights
    WHERE AccountId = @AccountId
      AND (@Since IS NULL OR DateStart >= @Since)
      AND (@Until IS NULL OR DateStop <= @Until)
    ORDER BY DateStart DESC;
END

GO
