CREATE PROCEDURE [dbo].[sp_Facebook_Insight_GetPage]
    @PageId  NVARCHAR(50),
    @Metric  NVARCHAR(200),
    @Since   DATETIME = NULL,
    @Until   DATETIME = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT Id, PageId, MetricName, Period, MetricValue, StartTime, EndTime, CreatedAt
    FROM Facebook_PageInsights
    WHERE PageId = @PageId
      AND MetricName = @Metric
      AND (@Since IS NULL OR StartTime >= @Since)
      AND (@Until IS NULL OR EndTime <= @Until)
    ORDER BY StartTime DESC;
END

