CREATE PROCEDURE [dbo].[sp_Facebook_Page_Save]
    @PageId         NVARCHAR(50),
    @PageName       NVARCHAR(255),
    @PageCategory   NVARCHAR(100) = NULL,
    @AccessToken    NVARCHAR(MAX) = NULL,
    @UserId         NVARCHAR(50)  = NULL,
    @FollowersCount INT           = 0,
    @LikesCount     INT           = 0,
    @IsPublished    BIT           = 1
AS
BEGIN
    SET NOCOUNT ON;
    MERGE Facebook_Pages AS target
    USING (SELECT @PageId AS PageId) AS source
    ON target.PageId = source.PageId
    WHEN MATCHED THEN
        UPDATE SET
            PageName       = @PageName,
            PageCategory   = @PageCategory,
            AccessToken    = @AccessToken,
            UserId         = @UserId,
            FollowersCount = @FollowersCount,
            LikesCount     = @LikesCount,
            IsPublished    = @IsPublished,
            UpdatedAt      = GETDATE()
    WHEN NOT MATCHED THEN
        INSERT (PageId, PageName, PageCategory, AccessToken, UserId, FollowersCount, LikesCount, IsPublished, CreatedAt, UpdatedAt)
