CREATE PROCEDURE [dbo].[sp_Facebook_Photo_Save]
    @PhotoId  NVARCHAR(50),
    @PageId   NVARCHAR(50)  = NULL,
    @UserId   NVARCHAR(50)  = NULL,
    @AlbumId  NVARCHAR(50)  = NULL,
    @Caption  NVARCHAR(MAX) = NULL,
    @Source   NVARCHAR(MAX) = NULL,
    @Link     NVARCHAR(MAX) = NULL,
    @Width    INT           = NULL,
    @Height   INT           = NULL
AS
BEGIN
    SET NOCOUNT ON;
    MERGE Facebook_Photos AS target
    USING (SELECT @PhotoId AS PhotoId) AS source
    ON target.PhotoId = source.PhotoId
    WHEN MATCHED THEN
        UPDATE SET Caption = @Caption, Source = @Source, Link = @Link, Width = @Width, Height = @Height, UpdatedAt = GETDATE()
    WHEN NOT MATCHED THEN
        INSERT (PhotoId, PageId, UserId, AlbumId, Caption, Source, Link, Width, Height, CreatedAt, UpdatedAt)
        VALUES (@PhotoId, @PageId, @UserId, @AlbumId, @Caption, @Source, @Link, @Width, @Height, GETDATE(), GETDATE());
END

