CREATE PROCEDURE [dbo].[sp_Facebook_User_Save]
    @UserId     NVARCHAR(50),
    @Name       NVARCHAR(255) = NULL,
    @Email      NVARCHAR(255) = NULL,
    @PictureUrl NVARCHAR(MAX) = NULL,
    @Locale     NVARCHAR(20)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    -- Log the user data into ApiLogs as a general record since there is no Facebook_Users table
    INSERT INTO Facebook_ApiLogs (UserId, ApiName, RequestBody, IsSuccess, CreatedAt)
    VALUES (@UserId, 'User_Save',
        CONCAT('{"name":"', @Name, '","email":"', @Email, '","locale":"', @Locale, '"}'),
        1, GETDATE());
END

