CREATE   PROCEDURE [dbo].[sp_Firebase_SaveToken]
    @ProjectId    NVARCHAR(256),
    @AccessToken  NVARCHAR(MAX),
    @RefreshToken NVARCHAR(MAX) = NULL,
    @ExpiresAt    DATETIME2,
    @Scope        NVARCHAR(1024) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM [dbo].[Firebase_Tokens] WHERE [ProjectId] = @ProjectId)
    BEGIN
        UPDATE [dbo].[Firebase_Tokens]
        SET [AccessToken]  = @AccessToken,
            [RefreshToken] = ISNULL(@RefreshToken, [RefreshToken]),
            [ExpiresAt]    = @ExpiresAt,
            [Scope]        = @Scope,
            [UpdatedAt]    = GETUTCDATE()
        WHERE [ProjectId] = @ProjectId;
    END
    ELSE
    BEGIN
        INSERT INTO [dbo].[Firebase_Tokens]
            ([ProjectId], [AccessToken], [RefreshToken], [ExpiresAt], [Scope])
        VALUES
            (@ProjectId, @AccessToken, @RefreshToken, @ExpiresAt, @Scope);
    END
END

GO
