CREATE   PROCEDURE [dbo].[sp_Firebase_SaveUser]
    @Uid            NVARCHAR(256),
    @ProjectId      NVARCHAR(256),
    @Email          NVARCHAR(256) = NULL,
    @EmailVerified  BIT = 0,
    @DisplayName    NVARCHAR(256) = NULL,
    @PhotoUrl       NVARCHAR(MAX) = NULL,
    @PhoneNumber    NVARCHAR(64)  = NULL,
    @Disabled       BIT = 0,
    @CreationTime   NVARCHAR(64)  = NULL,
    @LastSignInTime NVARCHAR(64)  = NULL,
    @ProviderData   NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM [dbo].[Firebase_Users] WHERE [Uid] = @Uid AND [ProjectId] = @ProjectId)
    BEGIN
        UPDATE [dbo].[Firebase_Users]
        SET [Email]          = ISNULL(@Email, [Email]),
            [EmailVerified]  = @EmailVerified,
            [DisplayName]    = ISNULL(@DisplayName, [DisplayName]),
            [PhotoUrl]       = ISNULL(@PhotoUrl, [PhotoUrl]),
            [PhoneNumber]    = ISNULL(@PhoneNumber, [PhoneNumber]),
            [Disabled]       = @Disabled,
            [LastSignInTime] = ISNULL(@LastSignInTime, [LastSignInTime]),
            [ProviderData]   = ISNULL(@ProviderData, [ProviderData])
        WHERE [Uid] = @Uid AND [ProjectId] = @ProjectId;
    END
    ELSE
    BEGIN
        INSERT INTO [dbo].[Firebase_Users]
            ([Uid], [ProjectId], [Email], [EmailVerified], [DisplayName], [PhotoUrl],
             [PhoneNumber], [Disabled], [CreationTime], [LastSignInTime], [ProviderData])
        VALUES
            (@Uid, @ProjectId, @Email, @EmailVerified, @DisplayName, @PhotoUrl,
             @PhoneNumber, @Disabled, @CreationTime, @LastSignInTime, @ProviderData);
    END
END

