CREATE   PROCEDURE [dbo].[sp_Flipkart_GetAllListings]
    @ListingStatus NVARCHAR(50) = NULL,
    @PageNo        INT = 1,
    @PageSize      INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    SELECT Id, SellerId, SkuId, ProductId, ListingStatus, Mrp, SellingPrice, Currency,
           FulfillmentProfile, Inventory, LocationId, CreatedAt, UpdatedAt
    FROM Flipkart_Listings
    WHERE (@ListingStatus IS NULL OR ListingStatus = @ListingStatus)
    ORDER BY UpdatedAt DESC
    OFFSET (@PageNo - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END

