    BEGIN
        UPDATE Flipkart_HyperLocalListings
        SET ProductId = @ProductId, ListingStatus = @ListingStatus,
            Mrp = @Mrp, SellingPrice = @SellingPrice,
            LocationId = @LocationId, Inventory = @Inventory, UpdatedAt = GETUTCDATE()
        WHERE SkuId = @SkuId;
    END
    ELSE
    BEGIN
        INSERT INTO Flipkart_HyperLocalListings (SkuId, ProductId, ListingStatus, Mrp, SellingPrice, LocationId, Inventory)
        VALUES (@SkuId, @ProductId, @ListingStatus, @Mrp, @SellingPrice, @LocationId, @Inventory);
    END
END

