CREATE   PROCEDURE [dbo].[sp_Flipkart_UpsertShipment]
    @ShipmentId     NVARCHAR(200),
    @OrderId        NVARCHAR(200),
    @OrderItemId    NVARCHAR(200),
    @State          NVARCHAR(100),
    @LocationId     NVARCHAR(100),
    @ShipmentType   NVARCHAR(50),
    @DispatchByDate DATETIME2
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM Flipkart_Shipments WHERE ShipmentId = @ShipmentId)
    BEGIN
        UPDATE Flipkart_Shipments
        SET OrderId = @OrderId, OrderItemId = @OrderItemId, State = @State,
            LocationId = @LocationId, ShipmentType = @ShipmentType,
            DispatchByDate = @DispatchByDate, UpdatedAt = GETUTCDATE()
        WHERE ShipmentId = @ShipmentId;
    END
    ELSE
    BEGIN
        INSERT INTO Flipkart_Shipments (ShipmentId, OrderId, OrderItemId, State, LocationId, ShipmentType, DispatchByDate)
        VALUES (@ShipmentId, @OrderId, @OrderItemId, @State, @LocationId, @ShipmentType, @DispatchByDate);
    END
END

GO
