CREATE   PROCEDURE [dbo].[sp_Identity_SaveContact]
    @ResourceName NVARCHAR(512),
    @UserId       NVARCHAR(256),
    @DisplayName  NVARCHAR(256) = NULL,
    @GivenName    NVARCHAR(256) = NULL,
    @FamilyName   NVARCHAR(256) = NULL,
    @Email        NVARCHAR(256) = NULL,
    @PhoneNumber  NVARCHAR(64)  = NULL,
    @PhotoUrl     NVARCHAR(1024) = NULL,
    @Organization NVARCHAR(256) = NULL,
    @JobTitle     NVARCHAR(256) = NULL,
    @Notes        NVARCHAR(MAX) = NULL,
    @Etag         NVARCHAR(256) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM [dbo].[Identity_Contacts] WHERE [ResourceName] = @ResourceName)
    BEGIN
        UPDATE [dbo].[Identity_Contacts]
        SET [UserId]       = @UserId,
            [DisplayName]  = @DisplayName,
            [GivenName]    = @GivenName,
            [FamilyName]   = @FamilyName,
            [Email]        = @Email,
            [PhoneNumber]  = @PhoneNumber,
            [PhotoUrl]     = @PhotoUrl,
            [Organization] = @Organization,
            [JobTitle]     = @JobTitle,
            [Notes]        = @Notes,
            [Etag]         = @Etag,
            [UpdatedAt]    = GETUTCDATE()
        WHERE [ResourceName] = @ResourceName;
    END
    ELSE
    BEGIN
        INSERT INTO [dbo].[Identity_Contacts]
            ([ResourceName], [UserId], [DisplayName], [GivenName], [FamilyName],
             [Email], [PhoneNumber], [PhotoUrl], [Organization], [JobTitle], [Notes], [Etag])
        VALUES
            (@ResourceName, @UserId, @DisplayName, @GivenName, @FamilyName,
             @Email, @PhoneNumber, @PhotoUrl, @Organization, @JobTitle, @Notes, @Etag);
    END
END

GO
