CREATE   PROCEDURE [dbo].[sp_Identity_SaveToken]
    @UserId       NVARCHAR(256),
    @AccessToken  NVARCHAR(MAX),
    @RefreshToken NVARCHAR(MAX) = NULL,
    @IdToken      NVARCHAR(MAX) = NULL,
    @ExpiresAt    DATETIME2,
    @Scope        NVARCHAR(1024) = NULL,
    @TokenType    NVARCHAR(50) = 'Bearer'
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM [dbo].[Identity_Tokens] WHERE [UserId] = @UserId)
    BEGIN
        UPDATE [dbo].[Identity_Tokens]
        SET [AccessToken]  = @AccessToken,
            [RefreshToken] = ISNULL(@RefreshToken, [RefreshToken]),
            [IdToken]      = ISNULL(@IdToken, [IdToken]),
            [ExpiresAt]    = @ExpiresAt,
            [Scope]        = @Scope,
            [TokenType]    = @TokenType,
            [UpdatedAt]    = GETUTCDATE()
        WHERE [UserId] = @UserId;
    END
    ELSE
    BEGIN
        INSERT INTO [dbo].[Identity_Tokens]
            ([UserId], [AccessToken], [RefreshToken], [IdToken], [ExpiresAt], [Scope], [TokenType])
        VALUES
            (@UserId, @AccessToken, @RefreshToken, @IdToken, @ExpiresAt, @Scope, @TokenType);
    END
END

