CREATE   PROCEDURE [dbo].[sp_Identity_SaveUser]
    @LocalId          NVARCHAR(256),
    @UserId           NVARCHAR(256) = NULL,
    @Email            NVARCHAR(256) = NULL,
    @EmailVerified    BIT = 0,
    @DisplayName      NVARCHAR(256) = NULL,
    @PhotoUrl         NVARCHAR(MAX) = NULL,
    @PhoneNumber      NVARCHAR(64) = NULL,
    @ProviderUserInfo NVARCHAR(MAX) = NULL,
    @CreatedAt        BIGINT = 0,
    @LastLoginAt      BIGINT = 0,
    @LastRefreshAt    NVARCHAR(64) = NULL,
    @Disabled         BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM [dbo].[Identity_Users] WHERE [LocalId] = @LocalId)
    BEGIN
        UPDATE [dbo].[Identity_Users]
        SET [UserId]           = ISNULL(@UserId, [UserId]),
            [Email]            = ISNULL(@Email, [Email]),
            [EmailVerified]    = @EmailVerified,
            [DisplayName]      = ISNULL(@DisplayName, [DisplayName]),
            [PhotoUrl]         = ISNULL(@PhotoUrl, [PhotoUrl]),
            [PhoneNumber]      = ISNULL(@PhoneNumber, [PhoneNumber]),
            [ProviderUserInfo] = ISNULL(@ProviderUserInfo, [ProviderUserInfo]),
            [LastLoginAt]      = @LastLoginAt,
            [LastRefreshAt]    = ISNULL(@LastRefreshAt, [LastRefreshAt]),
            [Disabled]         = @Disabled
        WHERE [LocalId] = @LocalId;
    END
    ELSE
    BEGIN
        INSERT INTO [dbo].[Identity_Users]
            ([LocalId], [UserId], [Email], [EmailVerified], [DisplayName], [PhotoUrl],
             [PhoneNumber], [ProviderUserInfo], [CreatedAt], [LastLoginAt], [LastRefreshAt], [Disabled])
        VALUES
            (@LocalId, @UserId, @Email, @EmailVerified, @DisplayName, @PhotoUrl,
             @PhoneNumber, @ProviderUserInfo, @CreatedAt, @LastLoginAt, @LastRefreshAt, @Disabled);
    END
END

