CREATE   PROCEDURE [dbo].[sp_Identity_UpdateContact]
    @ResourceName NVARCHAR(512),
    @UserId       NVARCHAR(256),
    @DisplayName  NVARCHAR(256) = NULL,
    @GivenName    NVARCHAR(256) = NULL,
    @FamilyName   NVARCHAR(256) = NULL,
    @Email        NVARCHAR(256) = NULL,
    @PhoneNumber  NVARCHAR(64)  = NULL,
    @PhotoUrl     NVARCHAR(1024) = NULL,
    @Organization NVARCHAR(256) = NULL,
    @JobTitle     NVARCHAR(256) = NULL,
    @Notes        NVARCHAR(MAX) = NULL,
    @Etag         NVARCHAR(256) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE [dbo].[Identity_Contacts]
    SET [DisplayName]  = ISNULL(@DisplayName, [DisplayName]),
        [GivenName]    = ISNULL(@GivenName, [GivenName]),
        [FamilyName]   = ISNULL(@FamilyName, [FamilyName]),
        [Email]        = ISNULL(@Email, [Email]),
        [PhoneNumber]  = ISNULL(@PhoneNumber, [PhoneNumber]),
        [PhotoUrl]     = ISNULL(@PhotoUrl, [PhotoUrl]),
        [Organization] = ISNULL(@Organization, [Organization]),
        [JobTitle]     = ISNULL(@JobTitle, [JobTitle]),
        [Notes]        = ISNULL(@Notes, [Notes]),
        [Etag]         = ISNULL(@Etag, [Etag]),
        [UpdatedAt]    = GETUTCDATE()
    WHERE [ResourceName] = @ResourceName AND [UserId] = @UserId;
END

