/****** Object:  StoredProcedure [dbo].[sp_Shopee_SaveAdCampaign]    Script Date: 7/11/2026 3:25:09 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

CREATE   PROCEDURE [dbo].[sp_Shopee_SaveAdCampaign]
    @ShopId          BIGINT,
    @CampaignId      BIGINT,
    @Name            NVARCHAR(200),
    @CampaignType    INT,
    @Status          NVARCHAR(50),
    @BudgetType      INT,
    @Budget          DECIMAL(18,2),
    @StartTime       BIGINT,
    @EndTime         BIGINT,
    @TotalImpression BIGINT,
    @TotalClick      BIGINT,
    @TotalCost       DECIMAL(18,2)
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM Shopee_AdCampaigns WHERE ShopId = @ShopId AND CampaignId = @CampaignId)
    BEGIN
        UPDATE Shopee_AdCampaigns
        SET Name = @Name, CampaignType = @CampaignType, Status = @Status,
            BudgetType = @BudgetType, Budget = @Budget, StartTime = @StartTime,
            EndTime = @EndTime, TotalImpression = @TotalImpression,
            TotalClick = @TotalClick, TotalCost = @TotalCost, UpdatedAt = GETDATE()
        WHERE ShopId = @ShopId AND CampaignId = @CampaignId;
    END
    ELSE
    BEGIN
        INSERT INTO Shopee_AdCampaigns (ShopId, CampaignId, Name, CampaignType, Status, BudgetType, Budget, StartTime, EndTime, TotalImpression, TotalClick, TotalCost)
        VALUES (@ShopId, @CampaignId, @Name, @CampaignType, @Status, @BudgetType, @Budget, @StartTime, @EndTime, @TotalImpression, @TotalClick, @TotalCost);
    END
END

GO
