CREATE   PROCEDURE [dbo].[sp_Shopee_SaveApiLog]
    @ShopId       BIGINT,
    @ApiName      NVARCHAR(200),
    @RequestBody  NVARCHAR(MAX),
    @ResponseBody NVARCHAR(MAX),
    @IsSuccess    BIT,
    @StatusCode   INT
AS
BEGIN
