    @Description      NVARCHAR(MAX) = NULL,
    @Location         NVARCHAR(500) = NULL,
    @StartDateTime    DATETIME2     = NULL,
    @EndDateTime      DATETIME2     = NULL,
    @StartTimeZone    NVARCHAR(100) = NULL,
    @EndTimeZone      NVARCHAR(100) = NULL,
    @Status           NVARCHAR(50)  = NULL,
    @HtmlLink         NVARCHAR(MAX) = NULL,
    @RecurringEventId NVARCHAR(255) = NULL,
    @Recurrence       NVARCHAR(MAX) = NULL,
    @Attendees        NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM [dbo].[Workspace_CalendarEvents] WHERE EventId = @EventId AND CalendarId = @CalendarId)
    BEGIN
        UPDATE [dbo].[Workspace_CalendarEvents]
        SET Summary = @Summary, Description = @Description, Location = @Location,
            StartDateTime = @StartDateTime, EndDateTime = @EndDateTime, Status = @Status,
            Attendees = @Attendees, UpdatedAt = GETUTCDATE()
        WHERE EventId = @EventId AND CalendarId = @CalendarId;
    END
    ELSE
    BEGIN
        INSERT INTO [dbo].[Workspace_CalendarEvents]
            (EventId, CalendarId, UserId, Summary, Description, Location, StartDateTime, EndDateTime,
             StartTimeZone, EndTimeZone, Status, HtmlLink, RecurringEventId, Recurrence, Attendees)
        VALUES
            (@EventId, @CalendarId, @UserId, @Summary, @Description, @Location, @StartDateTime, @EndDateTime,
             @StartTimeZone, @EndTimeZone, @Status, @HtmlLink, @RecurringEventId, @Recurrence, @Attendees);
    END
END

