    IF NOT EXISTS (SELECT 1 FROM [dbo].[Workspace_Presentations] WHERE PresentationId = @PresentationId AND UserId = @UserId)
    BEGIN
        INSERT INTO [dbo].[Workspace_Presentations] (PresentationId, UserId, Title, PresentationUrl, RevisionId)
        VALUES (@PresentationId, @UserId, @Title, @PresentationUrl, @RevisionId);
    END
END

