CREATE   PROCEDURE [dbo].[sp_Workspace_UpdateToken]
    @UserId       NVARCHAR(255),
    @AccessToken  NVARCHAR(MAX),
    @RefreshToken NVARCHAR(MAX),
    @ExpiresAt    DATETIME2,
    @Scope        NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE [dbo].[Workspace_Tokens]
    SET AccessToken = @AccessToken,
        RefreshToken = @RefreshToken,
        ExpiresAt = @ExpiresAt,
        Scope = ISNULL(@Scope, Scope),
        UpdatedAt = GETUTCDATE()
    WHERE UserId = @UserId;
END

